out=Path(r'D:\My Project\zero-to-tech\output\interview')
d=Document(); sec=d.sections[0]; sec.top_margin=sec.bottom_margin=Cm(2); sec.left_margin=sec.right_margin=Cm(2.2)
for name in ['Normal','Title','Heading 1','Heading 2']:
 s=d.styles[name]; s.font.name='Microsoft YaHei'; s.element.rPr.rFonts.set(qn('w:eastAsia'),'微软雅黑'); s.font.color.rgb=RGBColor(0,0,0)
d.styles['Normal'].font.size=Pt(10.5); d.styles['Normal'].paragraph_format.line_spacing=1.22; d.styles['Normal'].paragraph_format.space_after=Pt(6)
